<?php
namespace App\Http\Controllers; use App\Models\FollowUp; use Illuminate\Http\Request;
class FollowUpController extends Controller {public function index(Request $r){$q=FollowUp::with(['lead','assignedUser'])->where('company_id',$r->user()->company_id);if($r->status==='overdue')$q->where('status','pending')->where('scheduled_at','<',now());elseif($r->filled('status'))$q->where('status',$r->status);return view('followups.index',['followups'=>$q->orderBy('scheduled_at')->paginate(25)]);}public function complete(Request $r,FollowUp $followUp){abort_unless($followUp->company_id===$r->user()->company_id,403);$followUp->update(['status'=>'completed','completed_at'=>now()]);return back()->with('success','Follow-up completed.');}public function destroy(Request $r,FollowUp $followUp){abort_unless($followUp->company_id===$r->user()->company_id,403);$followUp->delete();return back()->with('success','Follow-up deleted.');}}
